# region: gather
def gather(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: digest
def digest(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return digest(intake(sift(shape(gather(raw)))))

